/// </summary>
[TFMDescription("Inverts a boolean value")]
class TFMLogicContextInverterOperator extends TFMLogicContextTools
{

}

Method.Source:
protected void new()
{
    super();
    inputTypes.add(TFMLogicContextTypes::Boolean);
    outputType = TFMLogicContextTypes::Boolean;
    noOfInput = 1; //Infinity
}

public Object process()
{
    Object ret;


    return ret;
}

public anytype evaluate(TFMLogicContext _context)
{
    anytype         ret = true;
    SetEnumerator   sEnum;
    TFMCondition    condition;
    if (children == null)
    {
        return ret;
    }
    sEnum = children.getEnumerator();
    while (sEnum.moveNext())
    {
        condition = sEnum.current();
        ret = !condition.evaluate(_context);
        break;
    }

    return ret;
}
